+/* Hash table helper for per-packet session context storage */
+static void
+nettrace_packet_ctx_free(void *data)
+{
+	nettrace_packet_ctx_t *ctx = (nettrace_packet_ctx_t *)data;
+	g_free(ctx->ue_id_type);
+	g_free(ctx->ue_id_value);
+	g_free(ctx);
+}
